import java.util.function.Consumer;
import java.util.function.Predicate;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanID;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ClanChannelChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.eventbus.Subscribe;

/**
 * Captures the local player's data and publishes it to the group store.
 * <p>
 * Changes are captured as they happen but published at most once per section interval, so a burst of
 * changes, like reorganising the bank, becomes one update.
 */
@Slf4j
@Singleton
public class LocalCollector
{
	/**
	 * Ticks to wait after login before reading the account, so names and containers are loaded.
	 */
	private static final int LOGIN_DELAY_TICKS = 2;

	/**
	 * Quests are read a little after login so the game has loaded them, otherwise a member would
	 * briefly appear to have finished nothing and then "complete" every quest at once.
	 */
	private static final int QUEST_DELAY_TICKS = 10;

	/**
	 * Quests are also re-read about once a minute, in case a completion was missed.
	 */
	private static final int QUEST_REFRESH_TICKS = 100;

	/**
	 * Ticks after a game message about quests before re-reading them, so a completion has registered.
	 */
	private static final int QUEST_MESSAGE_DELAY_TICKS = 2;

	private final Client client;
	private final Gson gson;

	private volatile SyncEngine engine;

	/**
	 * Hashed account id of the logged in player, or null when logged out.
	 */
	@Getter
	private volatile String memberId;

	private volatile ProfileData profile;

	/**
	 * Ticks since login while waiting to read the account, or -1 when not waiting.
	 */
	private int loginTicks = -1;

	/**
	 * Ticks until quests are next read, or -1 when no read is due.
	 */
	private int questTicks = -1;
	private int ticksSinceQuests;

	/**
	 * Told the Group Ironman group name each time it is read, on the client thread.
	 */
	private volatile Consumer<String> groupListener;

	/**
	 * Decides whether the logged in account's data belongs in the current group. Data waits until it
	 * does, so an alt that isn't in the group never shares anything.
	 */
	private volatile Predicate<ProfileData> sharePolicy = p -> true;

	/**
	 * Data captured but not yet published, newest copy per section. Concurrent, as are the publish
	 * times, since stopping the plugin clears them from the Swing thread while the client thread may
	 * be sending.
	 */
	private final Map<Section, Object> pending = new ConcurrentHashMap<>();
	private final Map<Section, Long> lastPublished = new ConcurrentHashMap<>();

	@Inject
	private LocalCollector(Client client, Gson gson)
	{
		this.client = client;
		this.gson = gson;
	}

	/**
	 * @return the logged in player's name, or null when logged out
	 */
	public String getLocalName()
	{
		ProfileData p = profile;
		return memberId == null || p == null ? null : p.getName();
	}

	public void setGroupListener(Consumer<String> groupListener)
	{
		this.groupListener = groupListener;
	}

	public void setSharePolicy(Predicate<ProfileData> sharePolicy)
	{
		this.sharePolicy = sharePolicy;
	}

	public void setEngine(SyncEngine engine)
	{
		this.engine = engine;
		lastPublished.clear();
		if (engine != null && memberId != null)
		{
			// switched group while logged in, so give the new group everything
			captureAll();
		}
	}

	public void start()
	{
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			loginTicks = 0;
		}
	}

	public void stop()
	{
		engine = null;
		questTicks = -1;
		groupListener = null;
		sharePolicy = p -> true;
		memberId = null;
		profile = null;
		loginTicks = -1;
		pending.clear();
		lastPublished.clear();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGGED_IN:
				if (memberId == null)
				{
					loginTicks = 0;
				}
				else
				{
					// back from a world hop or loading screen
					capture(Section.PROFILE, readProfile());
				}
				break;
			case HOPPING:
				flush(true);
				break;
			case LOGIN_SCREEN:
				if (memberId != null && profile != null)
				{
					// world 0 marks them logged out, and the record's version records when
					capture(Section.PROFILE, new ProfileData(profile.getName(), 0, profile.getGroupName()));
				}
				flush(true);
				memberId = null;
				profile = null;
				loginTicks = -1;
				questTicks = -1;
				pending.clear();
				break;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (loginTicks >= 0 && ++loginTicks >= LOGIN_DELAY_TICKS)
		{
			onLoggedIn();
		}
		if (memberId != null)
		{
			if (questTicks >= 0 && --questTicks <= 0)
			{
				questTicks = -1;
				ticksSinceQuests = 0;
				capture(Section.QUESTS, readQuests());
			}
			else if (questTicks < 0 && ++ticksSinceQuests >= QUEST_REFRESH_TICKS)
			{
				questTicks = 1;
			}
			flush(false);
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (memberId != null && DiaryVarbits.ALL.contains(event.getVarbitId()))
		{
			capture(Section.DIARIES, readDiaries());
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		// quest completions are announced in a game message, so check soon after one
		if (memberId != null && event.getType() == ChatMessageType.GAMEMESSAGE
			&& event.getMessage().toLowerCase(Locale.ROOT).contains("quest") && questTicks < 0)
		{
			questTicks = QUEST_MESSAGE_DELAY_TICKS;
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (memberId != null)
		{
			capture(Section.SKILLS, readSkills());
		}
	}

	@Subscribe
	public void onClanChannelChanged(ClanChannelChanged event)
	{
		// the group chat channel can load a few seconds after login, which is when we learn the group name
		if (event.getClanId() == ClanID.GROUP_IRONMAN && memberId != null)
		{
			capture(Section.PROFILE, readProfile());
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		Section section = sectionFor(event.getContainerId());
		if (section != null)
		{
			capture(section, ItemsData.of(event.getItemContainer()));
		}
	}

	private void onLoggedIn()
	{
		long accountHash = client.getAccountHash();
		Player player = client.getLocalPlayer();
		if (accountHash == -1 || player == null || player.getName() == null)
		{
			// not ready yet, try again next tick
			loginTicks = 0;
			return;
		}
		loginTicks = -1;
		memberId = Ids.member(accountHash);
		log.debug("Logged in as member {}", memberId);
		captureAll();
	}

	private void captureAll()
	{
		capture(Section.PROFILE, readProfile());
		capture(Section.SKILLS, readSkills());
		capture(Section.INVENTORY, ItemsData.of(client.getItemContainer(InventoryID.INV)));
		capture(Section.EQUIPMENT, ItemsData.of(client.getItemContainer(InventoryID.WORN)));
		capture(Section.DIARIES, readDiaries());
		questTicks = QUEST_DELAY_TICKS;
		flush(true);
	}

	/**
	 * Share something the player did, such as marking a tile. Sent on a later game tick, once the
	 * account is known to belong to the group. Call on the client thread.
	 */
	public void share(Section section, Object data)
	{
		capture(section, data);
	}

	/**
	 * @return our own copy of a section as last shared, or null if we haven't shared it
	 */
	public <T> T shared(Section section, Class<T> type)
	{
		SyncEngine engine = this.engine;
		String memberId = this.memberId;
		if (engine == null || memberId == null)
		{
			return null;
		}
		Object pendingData = pending.get(section);
		if (type.isInstance(pendingData))
		{
			// not sent yet, so round trip it to hand out a copy
			return gson.fromJson(gson.toJsonTree(pendingData), type);
		}
		SyncRecord record = engine.getStore().get(section.keyFor(memberId));
		if (record == null || record.getData() == null)
		{
			return null;
		}
		try
		{
			return Checkable.checked(gson.fromJson(record.getData(), type));
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private void capture(Section section, Object data)
	{
		if (data != null)
		{
			pending.put(section, data);
		}
	}

	private void flush(boolean force)
	{
		SyncEngine engine = this.engine;
		String memberId = this.memberId;
		ProfileData profile = this.profile;
		if (engine == null || memberId == null || profile == null || !sharePolicy.test(profile))
		{
			return;
		}

		long now = System.currentTimeMillis();
		for (Iterator<Map.Entry<Section, Object>> it = pending.entrySet().iterator(); it.hasNext(); )
		{
			Map.Entry<Section, Object> entry = it.next();
			Section section = entry.getKey();
			Long last = lastPublished.get(section);
			if (!force && last != null && now - last < section.getMinIntervalMs())
			{
				continue;
			}
			engine.publish(section.keyFor(memberId), memberId, gson.toJsonTree(entry.getValue()));
			lastPublished.put(section, now);
			it.remove();
		}
	}

	private ProfileData readProfile()
	{
		Player player = client.getLocalPlayer();
		if (player == null || player.getName() == null)
		{
			return null;
		}
		profile = new ProfileData(player.getName(), client.getWorld(), readGroupName());
		Consumer<String> listener = groupListener;
		if (listener != null && profile.getGroupName() != null)
		{
			listener.accept(profile.getGroupName());
		}
		return profile;
	}

	/**
	 * @return the player's Group Ironman group name, such as "HungryHorse", or null if they aren't in one
	 */
	private String readGroupName()
	{
		ClanChannel channel = client.getClanChannel(ClanID.GROUP_IRONMAN);
		if (channel != null && !Strings.isNullOrEmpty(channel.getName()))
		{
			return channel.getName();
		}
		ClanSettings settings = client.getClanSettings(ClanID.GROUP_IRONMAN);
		return settings == null ? null : Strings.emptyToNull(settings.getName());
	}

	private QuestsData readQuests()
	{
		QuestsData data = new QuestsData();
		for (Quest quest : Quest.values())
		{
			QuestState state = quest.getState(client);
			if (state == QuestState.FINISHED)
			{
				data.getQuests().put(quest.getName(), QuestsData.FINISHED);
			}
			else if (state == QuestState.IN_PROGRESS)
			{
				data.getQuests().put(quest.getName(), QuestsData.STARTED);
			}
		}
		return data;
	}

	private DiariesData readDiaries()
	{
		DiariesData data = new DiariesData();
		for (Map.Entry<String, int[]> region : DiaryVarbits.BY_REGION.entrySet())
		{
			int bits = 0;
			int[] varbits = region.getValue();
			for (int tier = 0; tier < varbits.length; tier++)
			{
				if (DiaryVarbits.isDone(varbits[tier], client.getVarbitValue(varbits[tier])))
				{
					bits |= 1 << tier;
				}
			}
			if (bits != 0)
			{
				data.getDone().put(region.getKey(), bits);
			}
		}
		return data;
	}

	private SkillsData readSkills()
	{
		SkillsData skills = new SkillsData();
		for (Skill skill : Skill.values())
		{
			skills.getXp().put(skill.name(), client.getSkillExperience(skill));
		}
		return skills;
	}

	private static Section sectionFor(int containerId)
	{
		switch (containerId)
		{
			case InventoryID.INV:
				return Section.INVENTORY;
			case InventoryID.WORN:
				return Section.EQUIPMENT;
			case InventoryID.BANK:
				return Section.BANK;
			case InventoryID.SEED_VAULT:
				return Section.SEED_VAULT;
			case InventoryID.LOOTING_BAG:
				return Section.LOOTING_BAG;
			case InventoryID.INV_GROUP_TEMP:
				return Section.GROUP_STORAGE;
			default:
				return null;
		}
	}
}

package com.homebase.data;

import java.util.ArrayList;
import java.util.List;
import lombok.Data;

/**
 * An item in group storage that some members can't take until they reach a goal. It's a soft lock:
 * the plugin hides the Withdraw options for those members, so it only binds people running it.
 */
@Data
public class BountyData implements Checkable
{
	private static final int MAX_MEMBERS = 100;

	private int itemId;
	private String itemName;

	/**
	 * Id of the goal that lifts the lock.
	 */
	private String goalId;

	/**
	 * Member ids locked out until they reach the goal.
	 */
	private List<String> locked = new ArrayList<>();

	/**
	 * How many are held back; anything more in group storage is free for anyone. 0 means all of
	 * them, as bounties made before amounts existed did.
	 */
	private int quantity;

	private String createdBy;
	private String createdByName;
	private long createdAt;

	@Override
	public void check()
	{
		locked = Checkable.list(locked, MAX_MEMBERS);
		quantity = Math.max(0, quantity);
	}
}

package com.homebase.data;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Data that arrives from other members' clients. Whatever those clients send could be malformed, so
 * after it's read, missing lists become empty, nulls are dropped and numbers are kept in range. The
 * rest of the plugin can then use it without checking every field.
 */
public interface Checkable
{
	/**
	 * Fix anything a malformed message left missing or out of range.
	 */
	void check();

	/**
	 * @return the same data, checked if it's a kind that can be
	 */
	static <T> T checked(T data)
	{
		if (data instanceof Checkable)
		{
			((Checkable) data).check();
		}
		return data;
	}

	/**
	 * @return the list without nulls and cut to {@code max} entries, or an empty list for none
	 */
	static <T> List<T> list(List<T> list, int max)
	{
		List<T> out = new ArrayList<>();
		if (list != null)
		{
			for (T value : list)
			{
				if (value != null && out.size() < max)
				{
					out.add(value);
				}
			}
		}
		return out;
	}

	/**
	 * @return the map without null keys or values, or an empty map for none
	 */
	static <K, V> Map<K, V> map(Map<K, V> map)
	{
		return map(map, Integer.MAX_VALUE);
	}

	/**
	 * @return the map without null keys or values and cut to {@code max} entries, or an empty map for none
	 */
	static <K, V> Map<K, V> map(Map<K, V> map, int max)
	{
		Map<K, V> out = new HashMap<>();
		if (map != null)
		{
			for (Map.Entry<K, V> entry : map.entrySet())
			{
				if (out.size() >= max)
				{
					break;
				}
				if (entry.getKey() != null && entry.getValue() != null)
				{
					out.put(entry.getKey(), entry.getValue());
				}
			}
		}
		return out;
	}

	/**
	 * @return the map without nulls, with every number between 0 and {@code maxValue}
	 */
	static <K> Map<K, Integer> counts(Map<K, Integer> map, int maxValue)
	{
		Map<K, Integer> out = map(map);
		out.replaceAll((key, value) -> Math.max(0, Math.min(maxValue, value)));
		return out;
	}
}

package com.homebase.data;

/**
 * Text typed by other players reaches our panel and chat box. Swing renders labels starting with
 * {@code <html>} as HTML, which can load remote images, and the chat box understands tags, so angle
 * brackets and control characters are stripped before anything is shown.
 */
public final class Clean
{
	private Clean()
	{
	}

	/**
	 * @return the text without tags or control characters, trimmed and cut to {@code max} characters,
	 * or null if nothing is left
	 */
	public static String text(String text, int max)
	{
		if (text == null)
		{
			return null;
		}
		StringBuilder sb = new StringBuilder(Math.min(text.length(), max));
		for (int i = 0; i < text.length() && sb.length() < max; i++)
		{
			char c = text.charAt(i);
			if (c != '<' && c != '>' && !Character.isISOControl(c))
			{
				sb.append(c);
			}
		}
		String out = sb.toString().trim();
		return out.isEmpty() ? null : out;
	}
}

package com.homebase.data;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * What a member has in their collection log. The game only reveals a page's items while it's open, so
 * pages are captured as the member browses them, and new slots are caught from the chat message.
 */
@Data
public class CollectionLogData implements Checkable
{
	private static final int MAX_PAGE_ITEMS = 500;

	/**
	 * Most recent new slots kept, newest first.
	 */
	public static final int MAX_RECENT = 20;

	/**
	 * Most pages kept, so a bad client can't flood everyone with junk.
	 */
	public static final int MAX_PAGES = 400;

	/**
	 * Unique slots filled, or 0 if the game hasn't told us yet.
	 */
	private int obtained;

	/**
	 * Unique slots in the whole log, or 0 if the game hasn't told us yet.
	 */
	private int total;

	/**
	 * Page name, such as "Vorkath", to what's on it.
	 */
	private Map<String, Page> pages = new HashMap<>();

	/**
	 * Names of the newest slots filled, newest first.
	 */
	private List<String> recent = new ArrayList<>();

	@Data
	@NoArgsConstructor
	@AllArgsConstructor
	public static class Page
	{
		/**
		 * How many items the page has.
		 */
		private int size;

		/**
		 * Ids of the items obtained on it.
		 */
		private List<Integer> items = new ArrayList<>();

		/**
		 * When the member last looked at the page.
		 */
		private long seen;
	}

	public void addRecent(String item)
	{
		recent.remove(item);
		recent.add(0, item);
		while (recent.size() > MAX_RECENT)
		{
			recent.remove(recent.size() - 1);
		}
	}

	@Override
	public void check()
	{
		pages = Checkable.map(pages, MAX_PAGES);
		for (Page page : pages.values())
		{
			page.setItems(Checkable.list(page.getItems(), MAX_PAGE_ITEMS));
		}
		recent = Checkable.list(recent, MAX_RECENT);
	}
}

package com.homebase.data;

import java.util.Arrays;
import java.util.List;
import lombok.Data;

@Data
public class CombatAchievementsData
{
	public static final List<String> TIERS = Arrays.asList("Easy", "Medium", "Hard", "Elite", "Master", "Grandmaster");

	private int points;

	/**
	 * How many tasks are done, across every tier.
	 */
	private int tasks;

	/**
	 * Highest entry of {@link #TIERS} whose points threshold has been reached, or -1 for none.
	 */
	private int tier = -1;

	public String tierName()
	{
		return tier >= 0 && tier < TIERS.size() ? TIERS.get(tier) : null;
	}
}

package com.homebase.data;

import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.Data;

@Data
public class DiariesData implements Checkable
{
	public static final List<String> TIERS = Arrays.asList("Easy", "Medium", "Hard", "Elite");

	public static final List<String> REGIONS = Arrays.asList(
		"Ardougne", "Desert", "Falador", "Fremennik", "Kandarin", "Karamja", "Kourend & Kebos",
		"Lumbridge & Draynor", "Morytania", "Varrock", "Western Provinces", "Wilderness");

	/**
	 * One bit set for each entry of {@link #TIERS}.
	 */
	private static final int ALL_TIERS = (1 << TIERS.size()) - 1;

	/**
	 * Region name to the tiers completed, one bit per entry of {@link #TIERS}.
	 */
	private Map<String, Integer> done = new HashMap<>();

	public boolean isDone(String region, int tier)
	{
		Integer bits = done.get(region);
		return bits != null && (bits & (1 << tier)) != 0;
	}

	public int countDone()
	{
		int n = 0;
		for (Integer bits : done.values())
		{
			n += bits == null ? 0 : Integer.bitCount(bits);
		}
		return n;
	}

	@Override
	public void check()
	{
		done = Checkable.counts(done, Integer.MAX_VALUE);
		// unknown regions and extra bits would push the number done past the total
		done.keySet().retainAll(REGIONS);
		done.replaceAll((region, tiers) -> tiers & ALL_TIERS);
	}
}

package com.homebase.data;

import java.util.ArrayList;
import java.util.List;
import lombok.Data;

/**
 * A target set for the group, such as "50 Firemaking" before Wintertodt. Goals tick off on their own
 * as each member's shared data shows they've reached it.
 */
@Data
public class GoalData implements Checkable
{
	private static final int MAX_MEMBERS = 100;

	public enum Type
	{
		SKILL,
		TOTAL_LEVEL,
		QUEST,
		DIARY,
		KILL_COUNT,
		COMBAT_POINTS,
		COLLECTION_LOG
	}

	/**
	 * A {@link Type} name, kept as text so a goal type added in a later version is ignored rather than
	 * breaking older clients.
	 */
	private String type;

	/**
	 * What the goal is about: a skill, quest, diary ("Varrock Easy") or boss name. Unused for totals.
	 */
	private String target;

	/**
	 * The level, kill count, points or slots needed. Unused for quests and diaries.
	 */
	private int amount;

	/**
	 * Member ids the goal applies to. Empty means everyone.
	 */
	private List<String> members = new ArrayList<>();

	private String createdBy;
	private String createdByName;
	private long createdAt;

	public Type typeOrNull()
	{
		try
		{
			return type == null ? null : Type.valueOf(type);
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	/**
	 * @return true if the goal applies to the member
	 */
	public boolean appliesTo(String memberId)
	{
		return members == null || members.isEmpty() || members.contains(memberId);
	}

	@Override
	public void check()
	{
		members = Checkable.list(members, MAX_MEMBERS);
	}
}

package com.homebase.data;

import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Predicate;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;

/**
 * Lookups the overlays need every frame, such as a member's combat level or everyone's marked tiles.
 * Worked out again only after the group's data changes, so drawing a frame never decodes records.
 */
@Singleton
public class GroupIndex
{
	/**
	 * Tile colour for members who haven't shared one.
	 */
	public static final Color DEFAULT_COLOR = new Color(0xFF9800);

	private static final int MAX_NAME = 20;

	@Value
	public static class MarkedTile
	{
		WorldPoint point;
		Color color;
		String name;
	}

	@Value
	public static class Highlight
	{
		int world;
		int index;
		int id;
		Color color;
		String name;
	}

	private static final class Snapshot
	{
		final Map<String, Integer> combatLevels = new HashMap<>();
		final Map<String, Color> colors = new HashMap<>();
		final Map<String, String> idsByName = new HashMap<>();
		final List<MarkedTile> tiles = new ArrayList<>();
		final List<Highlight> highlights = new ArrayList<>();
	}

	private volatile GroupView view;
	private volatile Predicate<ProfileData> belongs = p -> true;
	private volatile boolean dirty = true;
	private volatile Snapshot snapshot = new Snapshot();

	public void setView(GroupView view, Predicate<ProfileData> belongs)
	{
		this.view = view;
		this.belongs = belongs;
		dirty = true;
	}

	/**
	 * Group data changed. Cheap, so it's fine to call for every record.
	 */
	public void invalidate()
	{
		dirty = true;
	}

	/**
	 * @return the member's combat level worked out from their shared skills, or 0 if we don't know it
	 */
	public int combatLevel(String name)
	{
		Integer level = name == null ? null : current().combatLevels.get(key(name));
		return level == null ? 0 : level;
	}

	/**
	 * @return the colour the member chose for their tiles
	 */
	public Color color(String name)
	{
		Color color = name == null ? null : current().colors.get(key(name));
		return color == null ? DEFAULT_COLOR : color;
	}

	/**
	 * @return the member id for a player name, or null if they aren't in the group
	 */
	public String memberId(String name)
	{
		return name == null ? null : current().idsByName.get(key(name));
	}

	/**
	 * @return true if the member id belongs to someone in the group, so what they set up counts
	 */
	public boolean isMember(String memberId)
	{
		return memberId != null && current().idsByName.containsValue(memberId);
	}

	/**
	 * @return every tile marked by anyone in the group
	 */
	public List<MarkedTile> tiles()
	{
		return Collections.unmodifiableList(current().tiles);
	}

	/**
	 * @return every monster highlighted by anyone in the group
	 */
	public List<Highlight> highlights()
	{
		return Collections.unmodifiableList(current().highlights);
	}

	private Snapshot current()
	{
		if (dirty)
		{
			dirty = false;
			snapshot = build(view, belongs);
		}
		return snapshot;
	}

	private static Snapshot build(GroupView view, Predicate<ProfileData> belongs)
	{
		Snapshot out = new Snapshot();
		if (view == null)
		{
			return out;
		}
		// the view hands out checked data, so lists are never null and already capped
		for (String id : view.memberIds())
		{
			ProfileData profile = view.get(id, Section.PROFILE, ProfileData.class);
			String name = profile == null ? null : Clean.text(profile.getName(), MAX_NAME);
			if (name == null || !belongs.test(profile))
			{
				continue;
			}
			String key = key(name);
			out.idsByName.put(key, id);

			SkillsData skills = view.get(id, Section.SKILLS, SkillsData.class);
			if (skills != null && !skills.getXp().isEmpty())
			{
				out.combatLevels.put(key, Experience.getCombatLevel(
					skills.getLevel(Skill.ATTACK), skills.getLevel(Skill.STRENGTH), skills.getLevel(Skill.DEFENCE),
					skills.getLevel(Skill.HITPOINTS), skills.getLevel(Skill.MAGIC), skills.getLevel(Skill.RANGED),
					skills.getLevel(Skill.PRAYER)));
			}

			Color color = DEFAULT_COLOR;
			HighlightsData highlights = view.get(id, Section.HIGHLIGHTS, HighlightsData.class);
			if (highlights != null)
			{
				color = new Color(highlights.getColor() & 0xFFFFFF);
				for (HighlightsData.Npc npc : highlights.getNpcs())
				{
					out.highlights.add(new Highlight(highlights.getWorld(), npc.getIndex(), npc.getId(), color, name));
				}
			}
			TilesData tiles = view.get(id, Section.TILES, TilesData.class);
			if (tiles != null)
			{
				color = new Color(tiles.getColor() & 0xFFFFFF);
				for (TilesData.Tile tile : tiles.getTiles())
				{
					out.tiles.add(new MarkedTile(new WorldPoint(tile.getX(), tile.getY(), tile.getPlane()), color, name));
				}
			}
			out.colors.put(key, color);
		}
		return out;
	}

	private static String key(String name)
	{
		// the game sometimes writes the space in a name as a non-breaking one
		return name.replace('\u00A0', ' ').trim().toLowerCase(Locale.ROOT);
	}
}

package com.homebase.data;

import com.google.gson.Gson;
import com.homebase.sync.GroupStore;
import com.homebase.sync.Keys;
import com.homebase.sync.SyncRecord;
import java.util.ArrayList;
import java.util.List;
import lombok.extern.slf4j.Slf4j;

/**
 * Typed read access to the group store.
 */
@Slf4j
public class GroupView
{
	private final GroupStore store;
	private final Gson gson;

	public GroupView(GroupStore store, Gson gson)
	{
		this.store = store;
		this.gson = gson;
	}

	/**
	 * @return ids of every member we have a profile for
	 */
	public List<String> memberIds()
	{
		List<String> out = new ArrayList<>();
		for (SyncRecord record : store.withPrefix("m:"))
		{
			if (Section.PROFILE.getKey().equals(Keys.sectionOf(record.getKey())))
			{
				out.add(Keys.memberOf(record.getKey()));
			}
		}
		return out;
	}

	public <T> T get(String memberId, Section section, Class<T> type)
	{
		return decode(store.get(section.keyFor(memberId)), type);
	}

	/**
	 * @return when the data was captured, or 0 if we have none
	 */
	public long updatedAt(String memberId, Section section)
	{
		SyncRecord record = store.get(section.keyFor(memberId));
		return record == null ? 0 : record.getVersion();
	}

	/**
	 * @return who captured group-wide data, such as the last member to open the group storage
	 */
	public String authorOf(String memberId, Section section)
	{
		SyncRecord record = store.get(section.keyFor(memberId));
		return record == null ? null : record.getAuthor();
	}

	private <T> T decode(SyncRecord record, Class<T> type)
	{
		if (record == null)
		{
			return null;
		}
		try
		{
			return Checkable.checked(gson.fromJson(record.getData(), type));
		}
		catch (RuntimeException e)
		{
			log.debug("Unreadable record {}", record.getKey(), e);
			return null;
		}
	}
}

package com.homebase.data;

import java.util.ArrayList;
import java.util.List;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * The monsters one member has highlighted for the group. A monster is known by its index on the
 * world, which is the same for everyone there, so highlights only count on the world they were made.
 */
@Data
public class HighlightsData implements Checkable
{
	/**
	 * Most monsters one member can highlight at once.
	 */
	public static final int MAX_HIGHLIGHTS = 20;

	/**
	 * Colour as 0xRRGGBB.
	 */
	private int color;

	private int world;

	private List<Npc> npcs = new ArrayList<>();

	@Data
	@NoArgsConstructor
	@AllArgsConstructor
	public static class Npc
	{
		private int index;

		/**
		 * What kind of monster it is, so a new monster that later gets the same index isn't highlighted.
		 */
		private int id;
	}

	public boolean contains(int index, int id)
	{
		for (Npc npc : npcs)
		{
			if (npc.index == index && npc.id == id)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Highlight the monster, or stop highlighting it if it already is.
	 *
	 * @return true if it's now highlighted
	 */
	public boolean toggle(int index, int id)
	{
		if (remove(index, id))
		{
			return false;
		}
		if (npcs.size() >= MAX_HIGHLIGHTS)
		{
			npcs.remove(0);
		}
		npcs.add(new Npc(index, id));
		return true;
	}

	public boolean remove(int index, int id)
	{
		return npcs.removeIf(n -> n.index == index && n.id == id);
	}

	@Override
	public void check()
	{
		npcs = Checkable.list(npcs, MAX_HIGHLIGHTS);
	}
}

