		new Place("Wintertodt", 1630, 3944, 40),
		new Place("Lake Molch", 1365, 3632, 20),
		new Place("Farming Guild", 1248, 3720, 30),
		new Place("Mount Karuulm", 1311, 3807, 30),
		// Varlamore
		new Place("Civitas illa Fortis", 1700, 3100, 70),
		// Wilderness safe zone, checked before the Wilderness itself
		new Place("Ferox Enclave", 3130, 3631, 20),
		// Places off the main map
		new Place("Zanaris", 2412, 4434, 60),
		new Place("Motherlode Mine", 3760, 5670, 40),
		new Place("Keldagrim", 2885, 10200, 70),
		new Place("Guardians of the Rift", 3615, 9490, 40),
		// houses are instances built from room templates kept in this block
		new Place("Player-owned house", 1952, 7104, 96)
	);

	private AreaNames()
	{
	}

	public static String describe(WorldPoint point)
	{
		return point == null ? null : describe(point.getX(), point.getY());
	}

	public static String describe(int x, int y)
	{
		Place closest = closest(x, y);
		if (closest != null && closest.distance(x, y) <= closest.radius)
		{
			return closest.name;
		}

		int wildy = wildernessLevel(x, y);
		if (wildy > 0)
		{
			return (isUnderground(y) ? "Wilderness dungeon" : "Wilderness") + " (level " + wildy + ")";
		}

		if (isUnderground(y))
		{
			String above = describe(x, y - UNDERGROUND_OFFSET);
			if (UNKNOWN.equals(above))
			{
				return "Underground";
			}
			return (above.startsWith("near ") ? above.substring(5) : above) + " (underground)";
		}

		if (closest != null && closest.distance(x, y) <= closest.radius + NEAR_DISTANCE)
		{
			return "near " + closest.name;
		}
		return UNKNOWN;
	}

	/**
	 * @return the Wilderness level at a point, or 0 outside the Wilderness
	 */
	private static int wildernessLevel(int x, int y)
	{
		int surfaceY = y >= WILDERNESS_SOUTH + UNDERGROUND_OFFSET ? y - UNDERGROUND_OFFSET : y;
		if (x < WILDERNESS_WEST || x >= WILDERNESS_EAST || surfaceY < WILDERNESS_SOUTH || surfaceY >= WILDERNESS_NORTH)
		{
			return 0;
		}
		return (surfaceY - WILDERNESS_SOUTH) / ROWS_PER_LEVEL + 1;
	}

	private static boolean isUnderground(int y)
	{
		return y >= UNDERGROUND_SOUTH && y < UNDERGROUND_NORTH;
	}

	private static Place closest(int x, int y)
	{
		Place best = null;
		int bestScore = Integer.MAX_VALUE;
		for (Place place : PLACES)
		{
			// compare by how far outside each place's radius the point is, so a small place next to a
			// big one still wins when you're standing in it
			int score = place.distance(x, y) - place.radius;
			if (score < bestScore)
			{
				bestScore = score;
				best = place;
			}
		}
		return best;
	}
}

package com.homebase.map;

import com.homebase.HomebaseConfig;
import com.homebase.data.Clean;
import com.homebase.data.GroupIndex;
import com.homebase.party.GroupSync;
import com.homebase.party.PartyMembers;
import com.homebase.party.Presence;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;

/**
 * Online group members on the world map, moved as their positions arrive through the party.
 */
@Singleton
public class GroupWorldMap
{
	private static final int DOT_SIZE = 11;
	private static final int MAX_NAME = 20;

	private final WorldMapPointManager worldMapPointManager;
	private final PartyService partyService;
	private final GroupSync groupSync;
	private final GroupIndex index;
	private final HomebaseConfig config;
	private final Presence presence;

	/**
	 * Points we added, by party member id.
	 */
	private final Map<Long, WorldMapPoint> points = new HashMap<>();
	private final Map<Integer, BufferedImage> dots = new HashMap<>();

	@Inject
	private GroupWorldMap(WorldMapPointManager worldMapPointManager, PartyService partyService, GroupSync groupSync,
		GroupIndex index, HomebaseConfig config, Presence presence)
	{
		this.worldMapPointManager = worldMapPointManager;
		this.partyService = partyService;
		this.groupSync = groupSync;
		this.index = index;
		this.config = config;
		this.presence = presence;
	}

	/**
	 * Move everyone's markers. Runs on the client thread, a couple of times a second.
	 */
	public void update()
	{
		if (!config.worldMap() || !groupSync.isGroupParty())
		{
			clear();
			return;
		}

		PartyMember local = partyService.getLocalMember();
		Set<Long> seen = new HashSet<>();
		for (PartyMember member : PartyMembers.current(partyService))
		{
			WorldPoint coord = member.getCoord();
			String name = Clean.text(member.getDisplayName(), MAX_NAME);
			// the game already shows you on the map
			if (!presence.isOnline(member) || coord == null || name == null
				|| (local != null && local.getMemberId() == member.getMemberId()))
			{
				continue;
			}
			seen.add(member.getMemberId());

			BufferedImage dot = dot(index.color(name));
			String tooltip = name + " - " + AreaNames.describe(coord);
			WorldMapPoint point = points.get(member.getMemberId());
			if (point == null)
			{
				point = WorldMapPoint.builder()
					.worldPoint(coord)
					.image(dot)
					.name(name)
					.tooltip(tooltip)
					.snapToEdge(true)
					.jumpOnClick(true)
					.build();
				points.put(member.getMemberId(), point);
				worldMapPointManager.add(point);
			}
			else
			{
				point.setWorldPoint(coord);
				point.setImage(dot);
				point.setName(name);
				point.setTooltip(tooltip);
			}
		}

		for (Iterator<Map.Entry<Long, WorldMapPoint>> it = points.entrySet().iterator(); it.hasNext(); )
		{
			Map.Entry<Long, WorldMapPoint> entry = it.next();
			if (!seen.contains(entry.getKey()))
			{
				worldMapPointManager.remove(entry.getValue());
				it.remove();
			}
		}
	}

	public void clear()
	{
		for (WorldMapPoint point : points.values())
		{
			worldMapPointManager.remove(point);
		}
		points.clear();
	}

	private BufferedImage dot(Color color)
	{
		return dots.computeIfAbsent(color.getRGB(), rgb ->
		{
			BufferedImage image = new BufferedImage(DOT_SIZE, DOT_SIZE, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g = image.createGraphics();
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setColor(color);
			g.fillOval(1, 1, DOT_SIZE - 2, DOT_SIZE - 2);
			g.setColor(Color.BLACK);
			g.setStroke(new BasicStroke(1.2f));
			g.drawOval(1, 1, DOT_SIZE - 2, DOT_SIZE - 2);
			g.dispose();
			return image;
		});
	}
}

package com.homebase.overlay;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.List;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;

/**
 * Bars side by side on one line of an overlay panel. RuneLite's own panel squashes a row of bars to
 * nothing, and sizes a new one a frame late, so this row lays itself out.
 */
class BarRow implements LayoutableRenderableEntity
{
	private final List<ProgressBarComponent> bars;
	private final int barWidth;
	private final int barHeight;
	private final int gap;

	/**
	 * Space above and below the bars, so they don't touch the lines around them.
	 */
	private final int top;
	private final int bottom;

	private final Rectangle bounds = new Rectangle();
	private Point location = new Point();

	BarRow(List<ProgressBarComponent> bars, int barWidth, int barHeight, int gap, int top, int bottom)
	{
		this.bars = bars;
		this.barWidth = barWidth;
		this.barHeight = barHeight;
		this.gap = gap;
		this.top = top;
		this.bottom = bottom;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		int x = location.x;
		int tallest = 0;
		for (ProgressBarComponent bar : bars)
		{
			bar.setPreferredLocation(new Point(x, location.y + top));
			bar.setPreferredSize(new Dimension(barWidth, barHeight));
			tallest = Math.max(tallest, bar.render(graphics).height);
			x += barWidth + gap;
		}
		Dimension size = new Dimension(Math.max(0, x - gap - location.x), top + tallest + bottom);
		bounds.setLocation(location);
		bounds.setSize(size);
		return size;
	}

	@Override
	public Rectangle getBounds()
	{
		return bounds;
	}

	@Override
	public void setPreferredLocation(Point location)
	{
		this.location = location;
	}

	@Override
	public void setPreferredSize(Dimension size)
	{
		// the bars decide the row's size
	}
}

package com.homebase.overlay;

import com.homebase.HomebaseConfig;
import com.homebase.data.Clean;
import com.homebase.data.GroupIndex;
import com.homebase.map.AreaNames;
import com.homebase.party.GroupSync;
import com.homebase.party.PartyMembers;
import com.homebase.party.Presence;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * An on-screen box with each online group member's hitpoints, prayer and run energy as bars, their
 * combat level and where they are. Live numbers come from RuneLite's party; combat level comes from
 * shared skills.
 */
@Singleton
public class GroupHudOverlay extends OverlayPanel
{
	private static final Color AREA = new Color(0xBDBDBD);

	/**
	 * Bar colours, the same as the sidebar panel's (and RuneLite's Party panel's).
	 */
	private static final Color HP_FG = new Color(0, 146, 54, 230);
	private static final Color HP_BG = new Color(102, 15, 16, 230);
	private static final Color PRAY_FG = new Color(0, 149, 151);
	private static final Color PRAY_BG = Color.BLACK;
	private static final Color RUN_FG = new Color(0xC8A01E);
	private static final Color RUN_BG = new Color(0x3A3220);
	private static final int BAR_GAP = 3;

	private static final int MAX_NAME = 20;

	private final Client client;
	private final HomebaseConfig config;
	private final PartyService partyService;
	private final GroupSync groupSync;
	private final GroupIndex index;
	private final Presence presence;

	@Inject
	private GroupHudOverlay(Client client, HomebaseConfig config, PartyService partyService, GroupSync groupSync, GroupIndex index,
		Presence presence)
	{
		this.client = client;
		this.config = config;
		this.partyService = partyService;
		this.groupSync = groupSync;
		this.index = index;
		this.presence = presence;
		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.hudEnabled() || client.getGameState() != GameState.LOGGED_IN || !groupSync.isGroupParty())
		{
			return null;
		}
		List<PartyMember> members = visibleMembers();
		if (members.isEmpty())
		{
			return null;
		}

		HomebaseConfig.HudSize size = config.hudSize();
		Font font = fontFor(size);
		boolean compact = config.hudCompact();
		panelComponent.setPreferredSize(new Dimension(widthFor(size), 0));

		for (PartyMember member : members)
		{
			if (compact)
			{
				addCompact(member, font, size);
			}
			else
			{
				addFull(member, font, size);
			}
		}
		return super.render(graphics);
	}

	private List<PartyMember> visibleMembers()
	{
		PartyMember local = partyService.getLocalMember();
		boolean includeSelf = config.hudIncludeSelf();
		List<PartyMember> out = new ArrayList<>();
		for (PartyMember member : PartyMembers.current(partyService))
		{
			// a name that is nothing once cleaned would leave the title with no text to draw
			if (!presence.isOnline(member) || Clean.text(member.getDisplayName(), MAX_NAME) == null)
			{
				continue;
			}
			if (!includeSelf && local != null && local.getMemberId() == member.getMemberId())
			{
				continue;
			}
			out.add(member);
		}
		out.sort((a, b) -> String.CASE_INSENSITIVE_ORDER.compare(a.getDisplayName(), b.getDisplayName()));
		return out;
	}

	private void addFull(PartyMember member, Font font, HomebaseConfig.HudSize size)
	{
		String name = Clean.text(member.getDisplayName(), MAX_NAME);
		int level = index.combatLevel(name);
		panelComponent.getChildren().add(TitleComponent.builder()
			.text(level > 0 && config.hudLevel() ? name + "  (level " + level + ")" : name)
			.color(index.color(name))
			.build());
		addBars(member, size);
		WorldPoint coord = coordOf(member);
		if (config.hudPosition() && coord != null)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Area")
				.leftFont(font)
				.right(AreaNames.describe(coord))
				.rightColor(AREA)
				.rightFont(font)
				.build());
		}
	}

	private void addCompact(PartyMember member, Font font, HomebaseConfig.HudSize size)
	{
		String name = Clean.text(member.getDisplayName(), MAX_NAME);
		int level = index.combatLevel(name);
		panelComponent.getChildren().add(LineComponent.builder()
			.left(level > 0 && config.hudLevel() ? name + " (" + level + ")" : name)
			.leftColor(index.color(name))
			.leftFont(font)
			.build());
		addBars(member, size);
	}

	/**
	 * Hitpoints, prayer and run energy as bars side by side, in the colours of the sidebar panel.
	 */
	private void addBars(PartyMember member, HomebaseConfig.HudSize size)
	{
		// our own numbers come straight from the game, since the party only sends them once they change
		PartyMember local = partyService.getLocalMember();
		boolean self = local != null && local.getMemberId() == member.getMemberId();

		List<ProgressBarComponent> bars = new ArrayList<>();
		int maxHp = self ? client.getRealSkillLevel(Skill.HITPOINTS) : member.getStatBase(Skill.HITPOINTS);
		if (config.hudHitpoints() && maxHp > 0)
		{
			int hp = self ? client.getBoostedSkillLevel(Skill.HITPOINTS) : member.getStatBoost(Skill.HITPOINTS);
			bars.add(bar(hp, maxHp, hp + "/" + maxHp, HP_FG, HP_BG));
		}
		int maxPrayer = self ? client.getRealSkillLevel(Skill.PRAYER) : member.getStatBase(Skill.PRAYER);
		if (config.hudPrayer() && maxPrayer > 0)
		{
			int prayer = self ? client.getBoostedSkillLevel(Skill.PRAYER) : member.getStatBoost(Skill.PRAYER);
			bars.add(bar(prayer, maxPrayer, prayer + "/" + maxPrayer, PRAY_FG, PRAY_BG));
		}
		if (config.hudRunEnergy())
		{
			// the game counts run energy in hundredths of a percent
			int run = self ? client.getEnergy() / 100 : member.getRunEnergy();
			bars.add(bar(run, 100, run + "%", RUN_FG, RUN_BG));
		}
		if (bars.isEmpty())
		{
			return;
		}
		int width = widthFor(size) - 2 * ComponentConstants.STANDARD_BORDER;
		int each = (width - BAR_GAP * (bars.size() - 1)) / bars.size();
		panelComponent.getChildren().add(new BarRow(bars, each, barHeight(size), BAR_GAP, 1, 3));
	}

	private static ProgressBarComponent bar(int value, int max, String label, Color fg, Color bg)
	{
		ProgressBarComponent bar = new ProgressBarComponent();
		bar.setMinimum(0);
		bar.setMaximum(Math.max(1, max));
		bar.setValue(Math.max(0, Math.min(value, max)));
		bar.setLabelDisplayMode(ProgressBarComponent.LabelDisplayMode.TEXT_ONLY);
		bar.setCenterLabel(label);
		bar.setForegroundColor(fg);
		bar.setBackgroundColor(bg);
		bar.setFontColor(Color.WHITE);
		return bar;
	}

	private static int barHeight(HomebaseConfig.HudSize size)
	{
		switch (size)
		{
			case SMALL:
				return 12;
			case LARGE:
				return 18;
			default:
				return 15;
		}
	}

	/**
	 * Where a member is. The party only sends a position once the player moves, so after joining
	 * before login our own would be missing until we walk; ours is read from the game instead.
	 */
	private WorldPoint coordOf(PartyMember member)
	{
		PartyMember local = partyService.getLocalMember();
		Player player = client.getLocalPlayer();
		if (local != null && local.getMemberId() == member.getMemberId() && player != null)
		{
			return WorldPoint.fromLocalInstance(client, player.getLocalLocation());
		}
		return member.getCoord();
	}

	private static Font fontFor(HomebaseConfig.HudSize size)
	{
		switch (size)
		{
			case SMALL:
				return FontManager.getRunescapeSmallFont();
			case LARGE:
				return FontManager.getRunescapeBoldFont();
			default:
				return FontManager.getRunescapeFont();
		}
	}

	private static int widthFor(HomebaseConfig.HudSize size)
	{
		switch (size)
		{
			case SMALL:
				return 130;
			case LARGE:
				return 190;
			default:
				return 155;
		}
	}
}

package com.homebase.overlay;

import com.homebase.HomebaseConfig;
import com.homebase.data.GroupIndex;
