import com.homebase.data.HighlightsData;
import java.awt.Color;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class PingsTest
{
	@Test
	public void highlightsToggleAndAreCapped()
	{
		HighlightsData data = new HighlightsData();
		assertTrue(data.toggle(5, 100));
		assertTrue(data.contains(5, 100));
		// the same index on another kind of monster is a different monster
		assertFalse(data.contains(5, 101));
		assertFalse(data.toggle(5, 100));
		assertFalse(data.contains(5, 100));

		for (int i = 0; i < HighlightsData.MAX_HIGHLIGHTS + 3; i++)
		{
			data.toggle(i, 1);
		}
		assertEquals(HighlightsData.MAX_HIGHLIGHTS, data.getNpcs().size());
		// the oldest ones made room
		assertFalse(data.contains(0, 1));
		assertTrue(data.contains(HighlightsData.MAX_HIGHLIGHTS + 2, 1));
	}

	@Test
	public void pingsAgeAndFade()
	{
		Ping ping = new Ping(1, "Alice", Color.RED, 301, new WorldPoint(3200, 3200, 0), -1, -1, 1_000);
		assertFalse(ping.isNpc());
		assertEquals(0f, ping.age(1_000, 4_000), 0.001f);
		assertEquals(0.5f, ping.age(3_000, 4_000), 0.001f);
		assertEquals(1f, ping.age(9_000, 4_000), 0.001f);

		// bright for most of its life, gone at the end
		assertEquals(255, PingOverlay.fade(Color.RED, 0f, 255).getAlpha());
		assertTrue(PingOverlay.fade(Color.RED, 0.5f, 255).getAlpha() > 180);
		assertEquals(0, PingOverlay.fade(Color.RED, 1f, 255).getAlpha());
	}
}

package com.homebase.requests;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.homebase.data.RequestData;
import org.junit.Test;

public class RequestDeliveryTest
{
	@Test
	public void requestsMatchItemsByName()
	{
		assertTrue(RequestDelivery.sameItem("bronze dagger", "Bronze dagger"));
		assertTrue(RequestDelivery.sameItem("  Bronze   dagger ", "Bronze dagger"));
		assertFalse(RequestDelivery.sameItem("Bronze dagger", "Bronze dagger(p)"));
		assertFalse(RequestDelivery.sameItem(null, "Bronze dagger"));
	}

	@Test
	public void reservedOnlyUntilDone()
	{
		RequestData data = new RequestData();
		assertFalse(data.isReserved());
		data.keep(1205, 1);
		assertTrue(data.isReserved());
		data.setDone(true);
		assertFalse(data.isReserved());
	}

	@Test
	public void amountsAddUpUntilEverythingAskedForArrives()
	{
		RequestData data = new RequestData();
		data.setQuantity(500);

		// 200 put in, then 1000 more: only what's still needed is kept back
		data.keep(995, 200);
		assertEquals(200, data.getReservedQuantity());
		data.keep(995, 1000);
		assertEquals(500, data.getReservedQuantity());

		// taking out more than was kept only counts what was kept
		data.receive(300, true);
		assertEquals(200, data.getReservedQuantity());
		assertEquals(300, data.getDelivered());
		assertFalse(data.isDone());

		// the rest by trade finishes it
		data.receive(200, false);
		assertTrue(data.isDone());
		assertFalse(data.isReserved());
	}

	@Test
	public void partOfARequestIsStillOpen()
	{
		RequestData data = new RequestData();
		data.setQuantity(10);
		data.keep(453, 4);
		data.receive(4, true);
		assertEquals(4, data.getDelivered());
		assertFalse(data.isReserved());
		assertFalse(data.isDone());
		// what's left can be put in again
		data.keep(453, 10);
		assertEquals(6, data.getReservedQuantity());
	}

	@Test
	public void tradePartnerFromTheTradeScreens()
	{
		assertEquals("Bonscott Kid", RequestDelivery.partnerName("Trading With: Bonscott Kid"));
		assertEquals("Bonscott Kid", RequestDelivery.partnerName("<col=ffffff>Trading with:<br>Bonscott Kid</col>"));
		assertNull(RequestDelivery.partnerName("Trading With: "));
	}

	@Test
	public void playerNamesMatchHoweverSpacesAreWritten()
	{
		assertTrue(RequestDelivery.sameName("Bonscott Kid", "Bonscott Kid"));
		assertTrue(RequestDelivery.sameName("bonscott kid", "Bonscott Kid"));
		assertFalse(RequestDelivery.sameName("Bonscott Kid", "Goulashnicov"));
	}
}

package com.homebase.sync;

import com.google.gson.Gson;
import com.google.gson.JsonPrimitive;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.concurrent.TimeUnit;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Simulates a party of clients passing messages through the same encode/decode path the plugin uses.
 */
public class SyncEngineTest
{
	private static final long HOUR = TimeUnit.HOURS.toMillis(1);
	private static final long TODAY = 1_790_000_000_000L;

	private final Gson gson = new Gson();
	private final List<Node> nodes = new ArrayList<>();
	private long now = TODAY + 18 * HOUR;
	private int recordMessages;

	private final class Node
	{
		final String id;
		final GroupStore store = new GroupStore();
		final SyncEngine engine;
		boolean online;
		boolean summaryWanted;

		Node(String id)
		{
			this.id = id;
			this.engine = new SyncEngine(store, () -> now, new Random(id.hashCode()));
			nodes.add(this);
		}

		void publish(String section, String value)
		{
			engine.publish(Keys.member(id, section), id, new JsonPrimitive(value));
		}

		String valueOf(Node member, String section)
		{
			SyncRecord record = store.get(Keys.member(member.id, section));
			return record == null ? null : record.getData().getAsString();
		}
	}

	private static SyncRecord record(String member, String section, long version, String value)
	{
		return new SyncRecord(Keys.member(member, section), version, member, false, new JsonPrimitive(value));
	}

	private void join(Node node)
	{
		node.online = true;
		// the party service tells everyone, including the newcomer, that someone joined
		for (Node member : nodes)
		{
			if (member.online)
			{
				member.summaryWanted = true;
			}
		}
	}

	private void leave(Node node)
	{
		node.online = false;
		node.summaryWanted = false;
	}

	private void runFor(long millis)
	{
		for (long t = 0; t < millis; t += 1000)
		{
			now += 1000;
			for (Node node : nodes)
			{
				if (node.online)
				{
					flush(node);
				}
			}
		}
	}

	private void flush(Node sender)
	{
		try
		{
			if (sender.summaryWanted)
			{
				sender.summaryWanted = false;
				String packed = WireCodec.pack(gson.toJson(sender.engine.summary()));
				for (Node receiver : nodes)
				{
					if (receiver.online && receiver != sender)
					{
						Map<String, Long> summary = gson.fromJson(WireCodec.unpack(packed), WireCodec.SUMMARY_TYPE);
						if (receiver.engine.onSummary(summary))
						{
							receiver.summaryWanted = true;
						}
					}
				}
			}

			List<SyncRecord> due = sender.engine.takeDue(48_000, r -> 64);
			if (!due.isEmpty())
			{
				recordMessages++;
				String packed = WireCodec.pack(gson.toJson(due));
				for (Node receiver : nodes)
				{
					if (receiver.online && receiver != sender)
					{
						List<SyncRecord> records = gson.fromJson(WireCodec.unpack(packed), WireCodec.RECORDS_TYPE);
						receiver.engine.onRecords(records);
					}
				}
			}
		}
		catch (IOException e)
		{
			throw new AssertionError(e);
		}
	}

	@Test
	public void newestCopyOfEachMemberWinsIndependently()
	{
		// I last got bonscott1's data at 5pm and mundell's at 1pm.
		// Fred last got mundell's data at 4pm and bonscott1's at 2pm.
		Node me = new Node("me");
		Node fred = new Node("fred");
		me.engine.load(Arrays.asList(
			record("bonscott1", "inv", TODAY + 17 * HOUR, "bonscott1 at 5pm"),
			record("mundell", "inv", TODAY + 13 * HOUR, "mundell at 1pm")));
		fred.engine.load(Arrays.asList(
			record("bonscott1", "inv", TODAY + 14 * HOUR, "bonscott1 at 2pm"),
			record("mundell", "inv", TODAY + 16 * HOUR, "mundell at 4pm")));

		join(me);
		join(fred);
		runFor(10_000);

		Node bonscott1 = new Node("bonscott1");
		Node mundell = new Node("mundell");
		// I update Fred's copy of bonscott1, Fred updates my copy of mundell
		assertEquals("bonscott1 at 5pm", me.valueOf(bonscott1, "inv"));
		assertEquals("bonscott1 at 5pm", fred.valueOf(bonscott1, "inv"));
		assertEquals("mundell at 4pm", me.valueOf(mundell, "inv"));
		assertEquals("mundell at 4pm", fred.valueOf(mundell, "inv"));
	}

	@Test
	public void dataIsRelayedToMembersWhoNeverOverlap()
	{
		Node alice = new Node("alice");
		Node bob = new Node("bob");
		Node carol = new Node("carol");

		join(alice);
		join(bob);
		bob.publish("bank", "bob's bank");
		runFor(5_000);
		leave(bob);

		// carol has never been online with bob
		join(carol);
		runFor(10_000);

		assertEquals("bob's bank", carol.valueOf(bob, "bank"));
	}

	@Test
	public void sectionsAreVersionedSeparately()
	{
		Node alice = new Node("alice");
		Node bob = new Node("bob");
		alice.engine.load(Arrays.asList(
			record("bob", "bank", TODAY + 9 * HOUR, "bank at 9am"),
			record("bob", "skills", TODAY + 15 * HOUR, "skills at 3pm")));
		bob.engine.load(Arrays.asList(
			record("bob", "bank", TODAY + 12 * HOUR, "bank at noon"),
			record("bob", "skills", TODAY + 10 * HOUR, "skills at 10am")));

		join(alice);
		join(bob);
		runFor(10_000);

		assertEquals("bank at noon", alice.valueOf(bob, "bank"));
		assertEquals("skills at 3pm", alice.valueOf(bob, "skills"));
		assertEquals("bank at noon", bob.valueOf(bob, "bank"));
		assertEquals("skills at 3pm", bob.valueOf(bob, "skills"));
	}

	@Test
	public void onlyOneMemberRelaysWhenSeveralHoldTheSameData()
	{
		Node alice = new Node("alice");
		Node bob = new Node("bob");
		Node carol = new Node("carol");
		Node dave = new Node("dave");
		SyncRecord bank = record("alice", "bank", TODAY + 9 * HOUR, "alice's bank");
		alice.engine.load(Arrays.asList(bank));
		bob.engine.load(Arrays.asList(bank));
		carol.engine.load(Arrays.asList(bank));

		join(bob);
		join(carol);
		runFor(5_000);
		recordMessages = 0;

		join(dave);
		runFor(10_000);

		assertEquals("alice's bank", dave.valueOf(alice, "bank"));
		assertEquals("only one of bob and carol should send it", 1, recordMessages);
	}

	@Test
	public void memberDataCanOnlyBeWrittenByItsOwner()
	{
		Node alice = new Node("alice");
		SyncRecord forged = new SyncRecord(Keys.member("bob", "bank"), now, "mallory", false, new JsonPrimitive("forged"));
		assertEquals(0, alice.engine.onRecords(Arrays.asList(forged)));
		assertNull(alice.store.get(forged.getKey()));
	}

	@Test
	public void sharedDataCanBeWrittenByAnyone()
	{
		Node alice = new Node("alice");
		SyncRecord goal = new SyncRecord(Keys.shared("goal", "wt"), now, "bob", false, new JsonPrimitive("50 firemaking"));
		assertEquals(1, alice.engine.onRecords(Arrays.asList(goal)));
	}

	@Test
	public void versionsFarInTheFutureAreRejected()
	{
		Node alice = new Node("alice");
		SyncRecord future = record("bob", "bank", now + TimeUnit.DAYS.toMillis(30), "from the future");
		assertEquals(0, alice.engine.onRecords(Arrays.asList(future)));
	}

	@Test
	public void deletedItemsStayDeletedWhenAnOldCopyArrives()
	{
		Node alice = new Node("alice");
		Node bob = new Node("bob");
		String key = Keys.shared("request", "rune-scimitar");
		SyncRecord oldCopy = new SyncRecord(key, now - HOUR, "carol", false, new JsonPrimitive("make me a rune scimitar"));
		alice.engine.load(Arrays.asList(oldCopy));
		bob.engine.load(Arrays.asList(oldCopy));
		alice.engine.delete(key, "alice");

		join(alice);
		join(bob);
		runFor(10_000);

		assertNull(alice.store.get(key));
		assertNull(bob.store.get(key));
	}

	@Test
	public void unchangedDataIsNotRepublished()
	{
		Node alice = new Node("alice");
		assertNotNull(alice.engine.publish(Keys.member("alice", "inv"), "alice", new JsonPrimitive("x")));
		assertNull(alice.engine.publish(Keys.member("alice", "inv"), "alice", new JsonPrimitive("x")));
	}

	@Test
	public void versionsKeepIncreasingEvenIfTheClockGoesBack()
	{
		Node alice = new Node("alice");
		String key = Keys.member("alice", "inv");
		SyncRecord first = alice.engine.publish(key, "alice", new JsonPrimitive("first"));
		now -= HOUR;
		SyncRecord second = alice.engine.publish(key, "alice", new JsonPrimitive("second"));
		assertTrue(second.getVersion() > first.getVersion());
	}

	@Test
	public void summaryReportsWhenThePeerIsAhead()
	{
		GroupStore store = new GroupStore();
		SyncEngine engine = new SyncEngine(store, () -> now, new Random(1));
		engine.load(Arrays.asList(record("bob", "bank", now - HOUR, "old")));
		assertTrue(engine.onSummary(Collections.singletonMap(Keys.member("bob", "bank"), now)));
		assertFalse(engine.onSummary(Collections.singletonMap(Keys.member("bob", "bank"), now - 2 * HOUR)));
	}
}

package com.homebase.sync;

import com.google.gson.Gson;
import com.google.gson.JsonPrimitive;
import java.io.IOException;
import java.io.StringReader;
import java.io.StringWriter;
import java.util.Arrays;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import org.junit.Test;

public class WireCodecTest
{
	private final Gson gson = new Gson();

	@Test
	public void deepNestingIsRefused()
	{
		StringBuilder deep = new StringBuilder();
		for (int i = 0; i <= WireCodec.MAX_DEPTH; i++)
		{
			deep.append('[');
		}
		assertTrue(WireCodec.nestedTooDeep(deep.toString()));
		assertFalse(WireCodec.nestedTooDeep("[{\"d\":{\"pages\":{\"Zulrah\":{\"items\":[1,2]}}}}]"));
		// brackets inside text don't count
		assertFalse(WireCodec.nestedTooDeep("{\"note\":\"" + deep + "\\\"" + deep + "\"}"));

		try
		{
			WireCodec.unpack(WireCodec.pack(deep.toString()));
			fail();
		}
		catch (IOException expected)
		{
		}
	}

	@Test
	public void roundTrips() throws IOException
	{
		String json = "{\"hello\":\"world\",\"items\":[1,2,3]}";
		assertEquals(json, WireCodec.unpack(WireCodec.pack(json)));
	}

	@Test
	public void compressesRepetitiveData()
	{
		StringBuilder bank = new StringBuilder("[");
		for (int i = 0; i < 800; i++)
		{
			bank.append(i * 7).append(',').append(1).append(',');
		}
		bank.append("0]");
		String packed = WireCodec.pack(bank.toString());
		assertTrue(packed.length() < bank.length() / 2);
	}

	@Test(expected = IOException.class)
	public void refusesOversizedPayloads() throws IOException
	{
		char[] zeros = new char[WireCodec.MAX_INFLATED_BYTES + 1];
		Arrays.fill(zeros, '0');
		WireCodec.unpack(WireCodec.pack(new String(zeros)));
	}

	@Test(expected = IOException.class)
	public void refusesGarbage() throws IOException
	{
		WireCodec.unpack("not a real payload!");
	}

	@Test
	public void saveFileRoundTrips()
	{
		List<SyncRecord> records = Arrays.asList(
			new SyncRecord(Keys.member("alice", "bank"), 5, "alice", false, new JsonPrimitive("bank")),
			new SyncRecord(Keys.shared("goal", "1"), 6, "bob", true, null));
		StringWriter writer = new StringWriter();
		WireCodec.writeSave(gson, writer, records);
		assertEquals(records, WireCodec.readSave(gson, new StringReader(writer.toString())));
	}

	@Test
	public void unknownSaveFormatIsIgnored()
	{
		assertNull(WireCodec.readSave(gson, new StringReader("{\"format\":99,\"records\":[]}")));
	}
}

package com.homebase.updates;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.homebase.data.CombatAchievementsData;
import com.homebase.data.QuestsData;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class UpdateDiffTest
{
	private static final List<String> REGIONS = Arrays.asList("Varrock", "Wilderness");
	private static final List<String> TIERS = Arrays.asList("Easy", "Medium", "Hard", "Elite");

	@Test
	public void skillQuestAndDiaryChangesMakeOneChatLine()
	{
		Map<String, Integer> skillsBefore = new LinkedHashMap<>();
		skillsBefore.put("Attack", 40);
		skillsBefore.put("Magic", 15);
		Map<String, Integer> skillsAfter = new LinkedHashMap<>(skillsBefore);
		skillsAfter.put("Magic", 32);

		Map<String, String> questsBefore = new HashMap<>();
		Map<String, String> questsAfter = new HashMap<>();
		questsAfter.put("The Restless Ghost", QuestsData.FINISHED);

		Map<String, Integer> diariesBefore = new HashMap<>();
		Map<String, Integer> diariesAfter = Collections.singletonMap("Varrock", 0b0001);

		List<String> changes = new ArrayList<>();
		changes.addAll(UpdateDiff.skills(skillsBefore, skillsAfter));
		changes.addAll(UpdateDiff.quests(questsBefore, questsAfter));
		changes.addAll(UpdateDiff.diaries(diariesBefore, diariesAfter, REGIONS, TIERS));

		assertEquals(Arrays.asList("Magic 15 → 32", "completed The Restless Ghost", "completed the Varrock Easy diary"), changes);
		assertEquals("bonscott1: Magic 15 -> 32, completed The Restless Ghost, completed the Varrock Easy diary.",
			UpdateDiff.chatLine("bonscott1", changes));
	}

	@Test
	public void xpWithoutALevelIsNotNews()
	{
		Map<String, Integer> levels = Collections.singletonMap("Magic", 32);
		assertTrue(UpdateDiff.skills(levels, levels).isEmpty());
	}

	@Test
	public void aSkillMissingFromTheOldCopyIsNotAGain()
	{
		// a skill added in a game update shouldn't read as going from nothing to its level
		assertTrue(UpdateDiff.skills(Collections.emptyMap(), Collections.singletonMap("Sailing", 1)).isEmpty());
	}

	@Test
	public void startingAQuestIsNotNewsButFinishingItIs()
	{
		Map<String, String> before = Collections.singletonMap("Cook's Assistant", QuestsData.STARTED);
		assertTrue(UpdateDiff.quests(Collections.emptyMap(), before).isEmpty());
		assertEquals(Collections.singletonList("completed Cook's Assistant"),
			UpdateDiff.quests(before, Collections.singletonMap("Cook's Assistant", QuestsData.FINISHED)));
	}

	@Test
	public void lotsOfQuestsAreCounted()
	{
		Map<String, String> after = new HashMap<>();
		for (int i = 0; i < 12; i++)
		{
			after.put("Quest " + i, QuestsData.FINISHED);
		}
		assertEquals(Collections.singletonList("completed 12 quests"), UpdateDiff.quests(Collections.emptyMap(), after));
	}

	@Test
	public void onlyNewDiaryTiersAreListed()
	{
		Map<String, Integer> before = Collections.singletonMap("Varrock", 0b0001);
		Map<String, Integer> after = new HashMap<>();
		after.put("Varrock", 0b0011);
		after.put("Wilderness", 0b0001);
		assertEquals(Arrays.asList("completed the Varrock Medium diary", "completed the Wilderness Easy diary"),
			UpdateDiff.diaries(before, after, REGIONS, TIERS));
	}

	@Test
	public void combatAchievementTasksAndTier()
	{
		assertEquals(Arrays.asList("completed 3 combat achievements", "reached Medium combat achievements"),
			UpdateDiff.combatAchievements(10, 13, 0, 1, CombatAchievementsData.TIERS));
		assertEquals(Collections.singletonList("completed a combat achievement"),
			UpdateDiff.combatAchievements(10, 11, 1, 1, CombatAchievementsData.TIERS));
	}

	@Test
	public void noCombatAchievementLineFromNothing()
	{
		// tasks that hadn't loaded yet shouldn't look like a huge burst of completions
		assertTrue(UpdateDiff.combatAchievements(0, 300, -1, 4, CombatAchievementsData.TIERS).isEmpty());
	}

	@Test
	public void newCollectionLogSlotsByName()
	{
		List<String> before = Collections.singletonList("Abyssal whip");
		List<String> after = Arrays.asList("Dragon pickaxe", "Draconic visage", "Abyssal whip");
		assertEquals(Arrays.asList("new collection log slot: Draconic visage", "new collection log slot: Dragon pickaxe"),
			UpdateDiff.collectionLog(100, 102, before, after));
	}

	@Test
	public void collectionLogFallsBackToCount()
	{
		assertEquals(Collections.singletonList("filled 3 collection log slots"),
			UpdateDiff.collectionLog(100, 103, Collections.emptyList(), Collections.emptyList()));
		assertTrue(UpdateDiff.collectionLog(0, 103, Collections.emptyList(), Collections.emptyList()).isEmpty());
	}

	@Test
	public void killCountsThatWentUp()
	{
		Map<String, Integer> before = new HashMap<>();
		before.put("Vorkath", 10);
		before.put("Zulrah", 5);
		Map<String, Integer> after = new HashMap<>(before);
		after.put("Vorkath", 12);
		after.put("Barrows", 300);
		// Barrows is new to us, so its whole count isn't announced
		assertEquals(Collections.singletonList("Vorkath kill count 10 → 12"), UpdateDiff.killCounts(before, after));
	}

